function providerJsonRequest(work,prompts,name,schema,signal) {
  const payload={model:PROVIDER.model,reasoning:{effort:PROVIDER.reasoning_effort},store:false,max_output_tokens:work.limits.max_output_tokens,
    input:[{role:'system',content:[{type:'input_text',text:prompts.sys}]},{role:'user',content:[{type:'input_text',text:prompts.usr}]}],
    text:{format:{type:'json_schema',name,strict:true,schema}}};
  if(bytes(payload)>work.limits.max_request_bytes)throw Error('MISSION_UNIFIED_REQUEST_OVERFLOW');
  return {payload,signal};
}

// This feature changes only the operational meaning of an offered hostile intention.
// The native composer, after the route and before publication, owns legal realization.
function nativeIntentDirectorPrompt(work,payload){
  if(!nativeIntentResolution(work))return;
  const system=payload.input[0].content[0];
  const substitutions=[
    ['Offense solo encounter+sidepng+preparazione server.','Offense richiede encounter+sidepng ed esprime un’intenzione ostile condizionale.'],
    ['Offense richiede encounter e sidepng; server prepara dichiarazione e difesa prima del Fato.','Offense richiede encounter e sidepng ed esprime un’intenzione ostile condizionale.'],
    ['Per offense occorrono encounter_key ed entry_side=png: il server deve preparare una dichiarazione offensiva e la difesa prima del Fato.','Per offense occorrono encounter_key ed entry_side=png: proponi l’intenzione ostile, senza promettere una dichiarazione offensiva o una difesa.']
  ];
  for(const [before,after] of substitutions)system.text=system.text.replaceAll(before,after);
  system.text+='\n\nnative_intent_resolution_v1. entry_kind=offense indica un’intenzione ostile condizionale, non una dichiarazione meccanica già disponibile o un attacco a contatto promesso. Non scegliere mano, tecnica, bersaglio o valori meccanici. Dopo la proposta e prima del Fato, il server concretizza l’intenzione esclusivamente attraverso le offerte native legali: attacco, movimento oppure mancata esecuzione attestata. La ricevuta server decide quali azioni sono realmente avvenute e quali risposte meccaniche sono disponibili; non implicare una difesa quando non è stato dichiarato un attacco. Il parlato e l’intenzione restano distinti dai fatti meccanici.';
  if(bytes(payload)>work.limits.max_request_bytes)throw Error('MISSION_ROLE_DIRECTOR_REQUEST_OVERFLOW');
}

