    'preparation_receipt_id','publication_barrier','source_windows','next_state_receipt_id','director_proposal','source_context',
    ...(segmented?['source_revision','offense_slots']:[]),...(role?['role_interpretation','role_disposition']:[]),...(peerV2Flag(work)?['current_projection']:[])];
