      ||(p.source_context!==null&&p.source_context?.source_revision!==p.source_revision))
      throw Error('MISSION_SEGMENTED_CONTEXT_REVISION_MISMATCH');
    const slotIds=new Set(),actors=new Set();
    for(const slot of p.offense_slots){
