// Closed internal failure classes; raw RPC text, SQLSTATE and details never leave the service.
const readFailures=new WeakMap();
const transientReadSqlStates=new Set(['08000','08001','08003','08006','08007','40001','40P01','55P03','57014','53300','57P01','57P02','57P03']);
const forbiddenReadCodes=new Set(['42501','28000','28P01','PGRST301','PGRST302','PGRST303']);
export function missionReadError(kind){
 const safe=['transient','forbidden','invalid'].includes(kind)?kind:'invalid',error=Error('MISSION_READ_REJECTED');
 readFailures.set(error,safe);return error;
}
export function classifyMissionReadError(error,status=null){
 if(error&&typeof error==='object'&&readFailures.has(error))return error;
 const code=typeof error?.code==='string'?error.code:'';
 if(forbiddenReadCodes.has(code))return missionReadError('forbidden');
 if(transientReadSqlStates.has(code))return missionReadError('transient');
 if(code!=='')return missionReadError('invalid');
 const network=error?.name==='TypeError'&&/fetch|network|load failed/i.test(String(error?.message??''));
 if(status===0||error?.name==='AbortError'||error?.name==='TimeoutError'||network)return missionReadError('transient');
 return missionReadError('invalid');
}
export function missionReadFailureResponse(error,prefix){
 const kind=error&&typeof error==='object'?readFailures.get(error):null;
 const transient=kind==='transient',forbidden=kind==='forbidden';
 return {status:transient?503:forbidden?403:422,body:{code:prefix+(transient?'_TRANSIENT':forbidden?'_FORBIDDEN':'_INVALID'),
  retry:false,provider_retry_allowed:false,read_retry_allowed:transient}};
}
export async function directorNarrationRead(body,db){
 if(!exact(body,['schema_version','parent_request','parent_receipt_id'])
  ||body.schema_version!=='mission-director-narration-read/1'||!validateRequest(body.parent_request)||!uuid(body.parent_receipt_id))
  return {handled:false};
 try{
  const ctl=new AbortController();let timer;
  let r;
  try{r=await Promise.race([db.directorNarrationNext(body.parent_request,body.parent_receipt_id,{signal:ctl.signal}),
   new Promise((_,reject)=>{timer=setTimeout(()=>{ctl.abort();reject(missionReadError('transient'));},5000);})]);}
  finally{clearTimeout(timer);}
  const fields=['schema_version','status','parent_request','parent_receipt_id','parent_work_id','child_work_id','child_kind','source_window_id','child_request'];
  const q=body.parent_request;
  if(!exact(r,fields)||r.schema_version!=='mission-director-narration-chain/1'||!['none','ready'].includes(r.status)
   ||!validateRequest(r.parent_request)||r.parent_request.master_session_id!==q.master_session_id
   ||r.parent_request.event_id!==q.event_id||r.parent_request.request_key!==q.request_key
   ||r.parent_request.expected_revision!==q.expected_revision||r.parent_receipt_id!==body.parent_receipt_id)
   throw Error('chain_shape');
  if(r.status==='none'){
   if(['parent_work_id','child_work_id','child_kind','source_window_id','child_request'].some(k=>r[k]!==null))throw Error('chain_shape');
  }else if(!uuid(r.parent_work_id)||!uuid(r.child_work_id)||r.parent_work_id===r.child_work_id
   ||r.child_kind!=='narration'||!uuid(r.source_window_id)||!validateRequest(r.child_request)
   ||r.child_request.master_session_id!==q.master_session_id||r.child_request.event_id===q.event_id
   ||r.child_request.request_key===q.request_key)throw Error('chain_shape');
  return {handled:true,status:200,body:r};
 }catch(error){return {handled:true,...missionReadFailureResponse(error,'MISSION_DIRECTOR_NARRATION_READ')};}
}

// Status precedes output consumption. Diagnostics contain no provider prose.
const STATUS=['completed','failed','in_progress','cancelled','queued','incomplete'];
const REASONS=['max_output_tokens','max_messages','content_filter','steered'];
const CODES=['invalid_json_schema','context_length_exceeded','unsupported_value','model_not_found','rate_limit_exceeded','insufficient_quota'];
const TYPES=['invalid_request_error','rate_limit_error','server_error'];
const PARAMS=['model','input','reasoning.effort','text.format.schema'];
const record=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const id=x=>typeof x==='string'&&/^[A-Za-z0-9_-]{1,200}$/.test(x)?x:null;
function metricsOf(u){
  if(!record(u))return null;
  const a=u.input_tokens,b=u.output_tokens,c=u.output_tokens_details?.reasoning_tokens??0,d=u.total_tokens;
  if([a,b,c,d].some(x=>!Number.isSafeInteger(x)||x<0)||c>b||d!==a+b)return null;
  return {input_tokens:a,output_tokens:b,reasoning_tokens:c,total_tokens:d};
}
export function createResponsesProvider({apiKey,fetchFn=fetch}) {
 return {async create({payload,signal,onRawOutput}) {
  let r,x;
  let diagnostic={schema_version:'mission-provider-diagnostic/1',http_status:null,response_id:null,request_id:null,status:'ABSENT',incomplete_reason:'ABSENT',parse_state:'NOT_ATTEMPTED',usage_state:'IGNORED_NONTERMINAL',error_code:null,error_type:null,error_param:null};
  const fail=(code,result=null)=>{const e=Error(code);e.provider_diagnostic=diagnostic;if(result!==null)e.provider_result=result;return e;};
  try{r=await fetchFn('https://api.openai.com/v1/responses',{method:'POST',headers:{authorization:`Bearer ${apiKey}`,'content-type':'application/json'},body:JSON.stringify(payload),signal});}
  catch{throw fail('PROVIDER_TRANSPORT');}
  diagnostic.http_status=Number.isInteger(r.status)&&r.status>=100&&r.status<=599?r.status:null;
  diagnostic.request_id=id(r.headers?.get('x-request-id'));
  if(!r.ok){
   try{
    const reader=r.body?.getReader();let total=0;const chunks=[];
    if(reader){try{while(true){const part=await reader.read();if(part.done)break;total+=part.value.byteLength;if(total>4096){await reader.cancel();break;}chunks.push(part.value);}}finally{reader.releaseLock();}}
    if(reader&&total<=4096){const data=new Uint8Array(total);let offset=0;for(const chunk of chunks){data.set(chunk,offset);offset+=chunk.byteLength;}const error=JSON.parse(new TextDecoder().decode(data))?.error;
     diagnostic.error_code=CODES.includes(error?.code)?error.code:null;diagnostic.error_type=TYPES.includes(error?.type)?error.type:null;diagnostic.error_param=PARAMS.includes(error?.param)?error.param:null;}
   }catch{/* optional, bounded, nonauthoritative */}
   throw fail('PROVIDER_HTTP');
  }
  try{x=await r.json();}catch{throw fail('PROVIDER_ENVELOPE');}
  if(!record(x))throw fail('PROVIDER_ENVELOPE');
  diagnostic.response_id=id(x.id);diagnostic.status=STATUS.includes(x.status)?x.status:(x.status===undefined||x.status===null?'ABSENT':'UNKNOWN');
  diagnostic.incomplete_reason=REASONS.includes(x.incomplete_details?.reason)?x.incomplete_details.reason:(x.incomplete_details?.reason==null?'ABSENT':'UNKNOWN');
  if(!['completed','incomplete','failed','cancelled'].includes(x.status))throw fail('PROVIDER_NONTERMINAL');
  const metrics=metricsOf(x.usage);
  diagnostic.usage_state=metrics?'VALID':(x.usage==null?'MISSING':'INVALID');
  const result={status:x.status,raw_output:null,metrics,terminal:true};
  if(x.status!=='completed'){if(typeof onRawOutput==='function'){const captured=JSON.stringify(x.output??null);result.raw_output=captured;try{await onRawOutput({raw_output:captured,status:x.status,metrics,response_id:diagnostic.response_id,request_id:diagnostic.request_id});}catch{throw fail('MISSION_PROVIDER_OUTPUT_RETENTION_FAILED',result);}}throw fail({incomplete:'MISSION_PROVIDER_INCOMPLETE',failed:'MISSION_PROVIDER_FAILED',cancelled:'MISSION_PROVIDER_CANCELLED'}[x.status],result);}
  let raw=null,parse='MISSING';
  if(Array.isArray(x.output)){
   const messages=x.output.filter(o=>o?.type==='message');
   if(x.output.some(o=>!record(o)||!['message','reasoning'].includes(o.type)))parse='UNKNOWN_TYPE';
   else if(messages.length>1)parse='MULTIPLE';
   else if(messages.length===1){
    const content=messages[0].content;
    if(!Array.isArray(content))parse='MALFORMED';
    else if(content.some(c=>c?.type==='refusal'))parse='REFUSAL';
    else if(content.some(c=>!record(c)||c.type!=='output_text'))parse='UNKNOWN_TYPE';
    else if(content.length>1)parse='MULTIPLE';
    else if(content.length===1&&typeof content[0].text==='string'&&content[0].text.trim().length>0){raw=content[0].text;parse='VALID';}
   }
  }else if(x.output!==undefined&&x.output!==null)parse='MALFORMED';
  diagnostic.parse_state=parse;
  result.raw_output=raw;
  if(typeof onRawOutput==='function'){const captured=raw??JSON.stringify(x.output??null);result.raw_output=captured;try{await onRawOutput({raw_output:captured,status:x.status,metrics,response_id:diagnostic.response_id,request_id:diagnostic.request_id});}catch{throw fail('MISSION_PROVIDER_OUTPUT_RETENTION_FAILED',result);}}
  if(parse!=='VALID')throw fail('PROVIDER_SCHEMA',result);
  let realization;
  try{realization=JSON.parse(raw);}catch{diagnostic.parse_state='MALFORMED';throw fail('PROVIDER_SCHEMA',result);}
  if(metrics===null)throw fail('PROVIDER_SCHEMA',result);
  return {realization,status:x.status,raw_output:raw,metrics,terminal:true};
 }};
}

